        this.addAnnotation((ENamedElement)this.getGateway_FrameMappings(), source, new String[]{"documentation", "Frame Gateway: The entire source frame is mapped as it is onto the target frame (what in general is only possible inside of a common platform). In this case source and target frame should be the identical object."});
